import React from "react";
import { TypeAnimation } from "react-type-animation";

const Hero = () => {
  return (
    <section className="hero">
      <div className="container hero-container">
        {/* LEFT TEXT SECTION */}
        <div className="hero-text">
          <h1 className="slide-left delay-1">
            Hi, I’m <span className="highlight">Prince Rakholiya</span>
          </h1>

          <h2>
            a{" "}
            <TypeAnimation
              sequence={[
                "Full Stack Developer", 2000,
                "React JS Developer", 2000,
                "Web Developer", 2000,
              ]}
              wrapper="span"
              speed={50}
              repeat={Infinity}
              className="typing-text"
            />
          </h2>

          <p className="slide-left delay-2">
            I'm a passionate Full Stack and React JS Developer dedicated to building
            responsive, scalable, and high-performance web applications.  
            I love turning ideas into interactive digital experiences using clean code
            and modern technologies like React, Node.js, and Express.
          </p>

          <button className="btn-primary slide-left delay-3">View Project</button>
        </div>

        {/* RIGHT IMAGE SECTION */}
        <div className="hero-image">
          <img src="assets/image/hero-image.png" alt="Prince Rakholiya working" />
        </div>
      </div>
    </section>
  );
};

export default Hero;
